<?php
namespace Modules\Ran\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;
class ProductionReceiptRequest extends FormRequest {public function authorize():bool{return auth()->check();} public function rules():array{return ['receipt_date'=>'required|date','location_id'=>'required|integer','store_id'=>'required|integer','labour_cost'=>'nullable|numeric|min:0','other_cost'=>'nullable|numeric|min:0','notes'=>'nullable|string|max:2000','lines'=>'required|array|min:1','lines.*.production_order_line_id'=>'nullable|integer','lines.*.item_id'=>'required|integer','lines.*.lot_no'=>'nullable|string|max:60','lines.*.serial_no'=>'nullable|string|max:100','lines.*.quantity'=>'required|numeric|min:0.0001','lines.*.gross_weight'=>'nullable|numeric|min:0','lines.*.net_weight'=>'nullable|numeric|min:0','lines.*.stone_weight'=>'nullable|numeric|min:0','lines.*.fine_weight'=>'nullable|numeric|min:0','lines.*.material_cost'=>'nullable|numeric|min:0','lines.*.sale_price'=>'nullable|numeric|min:0'];}}
